attribute vec3 aO, aE; attribute float aT, aK; attribute vec4 aP; uniform float uTime; varying float vS, vY, vF, vFl, vSt;
    float h1(float x){ return fract(sin(x*127.1)*43758.5); }
    float jag(float s, float st, float k){ float x = s*k, i = floor(x); return mix(h1(mod(i, k) + st), h1(mod(i + 1., k) + st), fract(x)) - .5; }   // periodic in s: the coil closes without a step
    vec3 boltAt(float s, float st, vec3 A, vec3 B){                        // fractal zigzag (3 octaves), bowed a little
      vec3 d = B - A, sd = normalize(cross(d, vec3(0., 1., 0.))), up = normalize(cross(sd, d));
      float env = pow(sin(3.14159*s), .7), L = length(d);
      float j1 = jag(s, st, 7.) + .45*jag(s, st + 3., 19.) + .2*jag(s, st + 9., 43.);
      float j2 = jag(s, st + 7., 6.) + .45*jag(s, st + 11., 17.) + .2*jag(s, st + 13., 39.);
      return mix(A, B, s) + (sd*j1 + up*j2)*env*L*.11 + up*env*L*.05;
    }
    vec3 aimDir(float base, float sweep, float u){ float y = base + sweep*.42*sin(u*.6); return vec3(-sin(y), -.012, -cos(y)); }
    vec3 at(float s, float st, float u){
      if (aK > 4.5){                                   // bolt coiled along the beam
        vec3 d = aimDir(aP.x, aP.y, u), sd = normalize(cross(d, vec3(0., 1., 0.))), up = cross(sd, d);
        float L = 22.*clamp(u/.12, 0., 1.), a = s*L*1.6 + aP.w*6.28 - u*9.;
        float r = .2 + .06*jag(s, st, 30.);
        return aO + d*s*L + (sd*cos(a) + up*sin(a))*r + (sd*jag(s, st + 3., 60.) + up*jag(s, st + 5., 55.))*.08;
      }
      if (aK < .5){
        float a = s*6.28318*aP.w + aP.z*6.28 + u*2.5*aP.w, R = aP.y*(1. + .08*jag(s, st, 26.));
        return aO + vec3(cos(a)*R, aP.x + .09*jag(s, st*1.7 + 3., 20.) + .06*sin(a*2. + aP.z*9.), sin(a)*R);
      }
      vec3 A = aO, B = aE;
      if (aK > 2.5){                                   // ambient strike: a new outward direction every 0.16 s, from a coil point
        float idx = floor(u/.32 + aP.z), h = h1(idx*1.37 + aP.z*91.), h2 = h1(idx*2.11 + aP.z*37.), h3 = h1(idx*3.7 + aP.z*13.);
