      }
      if (aK < 1.5 || (aK > 2.5 && aK < 3.5)) return boltAt(s, st, A, B);
      // branch: forks off its main bolt at aP.x (same path, computed here), heads outward at angle aP.y for aP.w metres
      vec3 S = boltAt(aP.x, st, A, B), d = normalize(B - A), sd = normalize(cross(d, vec3(0., 1., 0.))), up = cross(sd, d);
      vec3 E2 = S + normalize(d*.6 + sd*cos(aP.y) + up*sin(aP.y))*aP.w;
      return boltAt(s, st + 17., S, E2);
    }
    void main(){
      float u = uTime - aT, life = aK < .5 || aK > 2.5 ? 3. : (aK < 1.5 ? .32 : .24);
      if (aK > 4.5) life = 6.;                       // coils hold ~3 s
      if (u < 0. || u > life){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float st = (aK > 4.5 ? floor(uTime*18.) : aK > 2.5 ?  floor((uTime - aT)/.32 + aP.z)*3.3 + floor(uTime*26.)*.0 : floor(uTime*(aK < .5 ? 20. : 14.))) + aP.z*50., s = position.x + .5;   // bolts re-strike faster
      float draw = aK < .5 ? clamp(u/.12, 0., 1.) : 1.;
      if (s > draw + .002){ gl_Position = vec4(2.,2.,2.,1.); return; }                                           // coil draws itself around in 0.12 s
      vec3 P = at(s, st, u), T = normalize(at(min(s + .01, 1.), st, u) - at(max(s - .01, 0.), st, u));
      vec3 side = normalize(cross(T, P - cameraPosition));
      float w = aK > 4.5 ? .035*(.4 + .6*smoothstep(0., .05, s)*smoothstep(1., .9, s)) : aK < .5 ? .05 : (aK < 1.5 ? .09 : aK > 2.5 && aK < 3.5 ? .028 : .018)*(.3 + .7*sin(3.14159*s));   // bolts taper at both ends
      vS = s; vY = position.y*2.; vSt = st; vFl = aK < .5 ? .7 + .3*h1(st*3.1) : step(.22, h1(st*3.1))*(.7 + .6*h1(st*1.7));;   // bolts strobe on/off like real strikes
      vF = aK > 4.5 ? .45*(1. - smoothstep(5.7, 6., u))*(.8 + .6*exp(-fract(u/.5)*9.)) : (u < .033 ? 1.8 : 1.)*(aK < .5 ? mix(1., .75, smoothstep(.2, .6, u))*(1. - smoothstep(2.6, 3., u)) : aK > 2.5 ? smoothstep(0., .04, fract(u/.32 + aP.z))*(1. - smoothstep(.22, .34, fract(u/.32 + aP.z)))*.45*(1. - smoothstep(2.6, 3., u))*1.3 : (1. - smoothstep(life*.55, life, u))*1.3);
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*w*3.2, 1.);   // wider strip: room for the soft glow
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vS, vY, vF, vFl, vSt;
    float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
    void main(){
      // electric "texture" (ref): thickness pulses along the strand, the hot core swells and pinches, the edge is a crackling fuzz
      float y = vY*1.6, sd = vSt*.37;
      float thick = .55 + .9*vn(vec2(vS*18. + sd, sd*3.)) + .5*pow(vn(vec2(vS*47. - sd, 5.)), 3.);   // uneven width
      float d = abs(y)/thick;
      float core = exp(-d*d*30.), glow = exp(-d*d*3.2)*.55, bloom = exp(-abs(y)*2.2)*.22;          // hot core, soft glow, wide faint bloom
      float fuzz = vn(vec2(vS*120. + sd*7., y*9. + sd)) * vn(vec2(vS*260. - sd*3., y*22.));         // tiny crackles on the edge
      float crack = smoothstep(.55, .9, fuzz)*exp(-d*d*.9)*(1. - core)*.9;
      float hot = pow(core, 1.5)*(.6 + .6*vn(vec2(vS*30. + sd*2., 1.)));                            // white-hot where the core swells
      vec3 o = (uOrange*(glow + bloom + crack*.8) + uGold*core*.7 + vec3(1., .96, .78)*hot*.55)*vF*vFl;
      o *= smoothstep(1., .75, abs(vY));
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.);
    }

